-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["8b0d0a7599348e6c"] = { "Mentre aspettavo i risultati di questi esperimenti, passai il tempo a parlare con Kegan. Sebbene lo incalzassi di continuo su ciò che sapeva delle sanguiniti, non mi disse mai più di quanto aveva detto il giorno in cui mi aveva dato il suo pendente. E non parlava spesso del periodo trascorso nelle file di quelli che chiamava \"i Reietti\", il nome che dà al suo clan di non morti.", "." },
  ["8b5a35e98333f326"] = { "Le auto a razzo che corrono sulle distese sono messe a punto con grande precisione e richiedono una manutenzione estrema. Non sorprende, quindi, che le squadre ai box restino sul posto in ogni momento.\n\nQueste squadre collaudano di continuo le loro auto e fanno riparazioni e modifiche quando serve. È l'unico modo per mantenere le auto in condizioni ottimali.\n\nQuindi... cerchiamo un mezzo per costringere una delle squadre ai box a un calo di attenzione, perché un calo del genere farebbe andare rapidamente in malora l'auto della squadra.", "." },
  ["8b5b8840ef729bfb"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nSCHEMA DEL PILASTRO OCCIDENTALE\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>", "." },
  ["8b725e067ddfef56"] = { "Per nostra sventura, gli immondi orchi sembrano più interessati alla rovina dei buoni sudditi di Sua Maestà. Nelle ultime due settimane il clan ⟦Blackrock=Roccianera⟧ ha sferrato un'offensiva spietata contro ⟦Lakeshire=Borgolago⟧. Molti uomini coraggiosi hanno perso la vita in quel giorno funesto. Le forze degli orchi sono avanzate con tale velocità e furia che il ponte sul Lago Placido è andato distrutto. Le nostre scorte di guerra sono molto diminuite. Ci mancano le bende per curare le ferite dei caduti.", "." },
  ["8bbac489f91466fc"] = { "⟦Solenor the Slayer=Solenor il Sicario⟧:\n\nNell'arido paesaggio di ⟦Silithus=Silitus⟧ si nasconde il demone ⟦Solenor the Slayer=Solenor il Sicario⟧. Di certo travestito, sicuramente pericoloso. Avvicinati e costringilo a trasformarsi.", "." },
  ["8bbf7ecb624d0977"] = { "Trova una picca grezza negli accampamenti degli Scarshield. Spesso le ammucchiano accanto ai loro giacigli, vicino all'ingresso del dominio degli ogre Spiraroccia.\n\nQuando avrai la picca, fatti strada fino al gran signore Omokk. Uccidilo e infilza la sua testa sulla picca.\n\nAllora potrai affrontare la vera sfida.", "." },
  ["8bed19e081e0618f"] = { "Ci piombarono addosso da ogni parte, artigliando da buche nascoste ai nostri piedi e calando su di noi da posatoi silenziosi in alto. Metà dei nostri uomini cadde in quei primi minuti di panico. Gli altri, me compreso, cercarono di fuggire. Mentre correvo vidi tanti miei fratelli presi da zanne e artigli, sentii tante grida spezzarsi di colpo o spegnersi in un gorgoglio.\n\nPer quanto ne so, sono l'unico umano fuggito da quel luogo.", "." },
})
